CREATE OR REPLACE FUNCTION public.finish_source_job(p_job_id uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.source_jobs%rowtype;
BEGIN
  SELECT * INTO j FROM public.source_jobs WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF p_success THEN
    PERFORM pgmq.delete('source_jobs',j.queue_msg_id);
    UPDATE public.source_jobs SET status='done',error_message=null,finished_at=now(),updated_at=now() WHERE id=p_job_id;
    RETURN true;
  END IF;
  PERFORM pgmq.archive('source_jobs',j.queue_msg_id);
  UPDATE public.source_jobs SET status='dead',error_message=left(coalesce(p_error,'worker failed'),1500),finished_at=now(),updated_at=now() WHERE id=p_job_id;
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_source_job_attempt(p_job_id uuid, p_attempt integer, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  j public.source_jobs%rowtype;
begin
  select * into j from public.source_jobs where id = p_job_id for update;
  if not found or j.attempts is distinct from p_attempt then
    return false;
  end if;
  -- Lost HTTP response after a committed acknowledgement: safe to repeat.
  if j.status = 'done' and p_success then return true; end if;
  if j.status in ('retry', 'dead') and not p_success then return true; end if;
  if j.status <> 'processing' then return false; end if;
  perform public.finish_source_job(p_job_id, p_success, p_error);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_ui_action(p_id uuid, p_token uuid, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j app_private.ui_action_jobs%rowtype;
begin
 update app_private.ui_action_jobs set status=case when p_error is null then 'done' else 'failed' end,finished_at=now(),error=left(p_error,200),lease_until=null
 where id=p_id and lease_token=p_token and status='processing' and lease_until>now() returning * into j;
 if not found then return false;end if;
 return not exists(select 1 from public.bot_events e join public.bot_users u on u.telegram_user_id=e.telegram_user_id where u.id=j.user_id and e.telegram_update_id>j.update_id);
end $function$

CREATE OR REPLACE FUNCTION public.finish_ui_update(p_update_id bigint, p_attempt integer, p_success boolean, p_error text DEFAULT NULL::text, p_timings jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare safe jsonb;
begin
 select coalesce(jsonb_object_agg(key,value),'{}') into safe from jsonb_each(coalesce(p_timings,'{}')) where key in ('prepare_ms','state_ms','render_ms','telegram_ms','total_ms','rpc_count','telegram_count','busy_count') and (case when jsonb_typeof(value)='number' then value::numeric else null end) between 0 and 600000;
 update public.bot_events set processing_status=case when p_success then 'done' else 'failed' end,processing_at=now(),processing_error=left(p_error,300),ui_timings=safe,
 payload=case when p_success and (left(coalesce(payload#>>'{message,reply_to_message,text}',''),1)='👤' or coalesce(payload#>>'{message,text}','')~'https://(tenant[.]immomio[.]com/de/auth/login|login[.]kleinanzeigen[.]de/android/com[.]ebay[.]kleinanzeigen/callback)') then jsonb_build_object('update_id',p_update_id,'redacted','private_applicant_input') else payload end
 where telegram_update_id=p_update_id and processing_status='processing' and processing_attempt=p_attempt;
 return found;
end $function$

CREATE OR REPLACE FUNCTION public.issue_coach_bootstrap_token(p_ttl_minutes integer DEFAULT 120)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
begin
  if p_ttl_minutes < 10 or p_ttl_minutes > 1440 then
    raise exception 'invalid_ttl';
  end if;

  if exists(
    select 1
    from public.coaching_members
    where role='admin' and is_active
  ) then
    raise exception 'admin_already_exists';
  end if;

  update app_private.coach_bootstrap_tokens
  set consumed_at=coalesce(consumed_at,now())
  where consumed_at is null;

  v_token := 'setup_'||encode(extensions.gen_random_bytes(32),'hex');

  insert into app_private.coach_bootstrap_tokens(token_hash,expires_at)
  values(
    encode(extensions.digest(v_token,'sha256'),'hex'),
    now()+make_interval(mins=>p_ttl_minutes)
  );

  return v_token;
end
$function$

CREATE OR REPLACE FUNCTION public.issue_telegram_link_token(p_user uuid, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
begin
  if not exists(
    select 1 from public.bot_users
    where id=p_user and is_active and telegram_user_id is null and chat_id is null
  ) then
    raise exception 'participant_not_linkable';
  end if;

  update app_private.telegram_link_tokens
  set invalidated_at=now()
  where user_id=p_user
    and consumed_at is null
    and invalidated_at is null;

  v_token := 'link_'||encode(extensions.gen_random_bytes(24),'hex');

  insert into app_private.telegram_link_tokens(
    user_id,token_hash,created_by,expires_at
  )
  values(
    p_user,
    encode(extensions.digest(v_token,'sha256'),'hex'),
    p_created_by,
    now()+interval '20 minutes'
  );

  return v_token;
end
$function$

CREATE OR REPLACE FUNCTION public.prepare_telegram_fast_action(p_payload jsonb, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base jsonb;
  v_claim integer;
  v_user jsonb;
  v_subscription jsonb;
  v_user_id uuid;
  v_is_premium boolean := false;
  v_limit integer := 1;
  v_data jsonb := '{}'::jsonb;
  v_slot integer;
  v_profiles jsonb;
  v_saved jsonb;
  v_saved_count integer;
begin
  v_base := public.prepare_telegram_update(p_payload);
  v_claim := coalesce((v_base->>'claim')::integer, 0);
  if v_claim <= 0 then return v_base; end if;

  v_user := v_base->'user';
  v_subscription := v_base->'subscription';
  v_user_id := (v_user->>'id')::uuid;

  v_is_premium := case
    when v_user->>'plan_override' = 'free' then false
    when v_user->>'plan_override' = 'premium'
      and (nullif(v_user->>'plan_override_expires_at','') is null or (v_user->>'plan_override_expires_at')::timestamptz > now()) then true
    when nullif(v_user->>'referral_bonus_until','') is not null and (v_user->>'referral_bonus_until')::timestamptz > now() then true
    when v_subscription is not null
      and coalesce(v_subscription->>'status','') in ('active','trialing')
      and (nullif(v_subscription->>'current_period_end','') is null or (v_subscription->>'current_period_end')::timestamptz > now()) then true
    else false
  end;
  v_limit := case when v_is_premium then 4 else 1 end;

  if coalesce(v_user->>'ui_language','de') <> 'de' then
    return v_base || jsonb_build_object('is_premium', v_is_premium, 'fast_eligible', false, 'action_data', v_data);
  end if;

  if p_action in ('profile','new') then
    select coalesce(jsonb_agg(jsonb_build_object('profile_slot',sp.profile_slot,'name',sp.name,'is_active',sp.is_active) order by sp.profile_slot), '[]'::jsonb)
    into v_profiles
    from public.search_profiles sp
    where sp.user_id = v_user_id and sp.profile_slot <= v_limit;
    v_data := v_data || jsonb_build_object('profiles', v_profiles, 'profile_limit', v_limit);
  end if;

  if p_action = 'new' then
    select s into v_slot
    from generate_series(1, v_limit) s
    where not exists (select 1 from public.search_profiles sp where sp.user_id = v_user_id and sp.profile_slot = s)
    order by s limit 1;
    if v_slot is not null then
      update public.bot_users
      set onboarding_step='types', onboarding_state=jsonb_build_object(
        'profile_slot',v_slot,'property_types',jsonb_build_array(),'location_mode',null,
        'borough_ids',jsonb_build_array(),'neighborhood_ids',jsonb_build_array(),'neighborhood_page',0,
        'max_warm_rent',null,'min_rooms',null,'min_area_sqm',null), updated_at=now()
      where id=v_user_id;
      v_data := v_data || jsonb_build_object('new_slot',v_slot);
    else
      v_data := v_data || jsonb_build_object('new_slot',null);
    end if;
  elsif p_action in ('pause','resume') then
    update public.search_profiles set is_active=(p_action='resume'), updated_at=now() where user_id=v_user_id;
    v_data := v_data || jsonb_build_object('paused',p_action='pause');
  elsif p_action='status' then
    v_data := v_data || jsonb_build_object(
      'profile_limit',v_limit,
      'active_profiles',(select count(*) from public.search_profiles sp where sp.user_id=v_user_id and sp.is_active=true and sp.profile_slot<=v_limit),
      'source_count',(select count(*) from public.sources),
      'referral_count',(select count(*) from public.referrals r where r.referrer_user_id=v_user_id and r.status='rewarded'));
  elsif p_action='saved' and v_is_premium then
    select count(*) into v_saved_count from public.saved_listings sl where sl.user_id=v_user_id;
    select coalesce(jsonb_agg(x.row_data order by x.created_at desc),'[]'::jsonb) into v_saved
    from (
      select sl.created_at, jsonb_build_object(
        'listing_id',sl.listing_id,'created_at',sl.created_at,
        'listing',jsonb_build_object('title',l.title,'canonical_url',l.canonical_url,'is_active',l.is_active)) row_data
      from public.saved_listings sl join public.listings l on l.id=sl.listing_id
      where sl.user_id=v_user_id order by sl.created_at desc limit 8
    ) x;
    v_data := v_data || jsonb_build_object('saved_count',v_saved_count,'saved',v_saved);
  end if;

  return v_base || jsonb_build_object('is_premium',v_is_premium,'fast_eligible',true,'action_data',v_data);
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_telegram_fast_request(p_payload jsonb, p_action text, p_supplied_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expected text;
  v_result jsonb;
begin
  v_expected := public.get_bot_secret('telegram_webhook_secret');
  if v_expected is null or p_supplied_secret is distinct from v_expected then
    return jsonb_build_object('authorized', false);
  end if;

  v_result := public.prepare_telegram_fast_action(p_payload, p_action);
  return jsonb_build_object('authorized', true) || v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_telegram_update(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_claim integer;
  v_update_id bigint := (p_payload->>'update_id')::bigint;
  v_user_id bigint := coalesce(
    (p_payload #>> '{callback_query,from,id}')::bigint,
    (p_payload #>> '{message,from,id}')::bigint
  );
  v_chat_id bigint := coalesce(
    (p_payload #>> '{callback_query,message,chat,id}')::bigint,
    (p_payload #>> '{message,chat,id}')::bigint
  );
  v_username text := coalesce(
    p_payload #>> '{callback_query,from,username}',
    p_payload #>> '{message,from,username}'
  );
  v_first_name text := coalesce(
    p_payload #>> '{callback_query,from,first_name}',
    p_payload #>> '{message,from,first_name}'
  );
  v_last_name text := coalesce(
    p_payload #>> '{callback_query,from,last_name}',
    p_payload #>> '{message,from,last_name}'
  );
  v_language_code text := coalesce(
    p_payload #>> '{callback_query,from,language_code}',
    p_payload #>> '{message,from,language_code}'
  );
  v_text text := coalesce(p_payload #>> '{message,text}','');
  v_start_param text;
  v_target uuid;
  v_link_id uuid;
  v_user public.bot_users%rowtype;
  v_subscription public.user_subscriptions%rowtype;
  v_is_new boolean := false;
begin
  if v_user_id is null or v_chat_id is null then
    raise exception 'missing telegram user or chat id';
  end if;

  v_claim := public.claim_telegram_update(p_payload);
  if v_claim <= 0 then
    return jsonb_build_object('claim',v_claim);
  end if;

  if v_text ~ '^/start[[:space:]]+link_[A-Za-z0-9_-]{20,64}$' then
    v_start_param := regexp_replace(v_text,'^/start[[:space:]]+','','');

    select t.id,t.user_id
      into v_link_id,v_target
    from app_private.telegram_link_tokens t
    where t.token_hash=encode(extensions.digest(v_start_param,'sha256'),'hex')
      and t.consumed_at is null
      and t.invalidated_at is null
      and t.expires_at>now()
    for update;

    if v_target is not null then
      if exists(
        select 1 from public.bot_users
        where telegram_user_id=v_user_id and id<>v_target
      ) then
        raise exception 'telegram_identity_conflict';
      end if;

      select * into v_user
      from public.bot_users
      where id=v_target
      for update;

      if not found or not v_user.is_active then
        raise exception 'telegram_link_target_unavailable';
      end if;

      if (v_user.telegram_user_id is not null and v_user.telegram_user_id<>v_user_id)
         or (v_user.chat_id is not null and v_user.chat_id<>v_chat_id)
      then
        raise exception 'telegram_identity_conflict';
      end if;

      update public.bot_users
      set telegram_user_id=v_user_id,
          chat_id=v_chat_id,
          username=v_username,
          first_name=coalesce(first_name,v_first_name),
          last_name=coalesce(last_name,v_last_name),
          language_code=v_language_code,
          last_start_at=now(),
          updated_at=now()
      where id=v_target
      returning * into v_user;

      update app_private.telegram_link_tokens
      set consumed_at=now()
      where id=v_link_id;
    end if;
  end if;

  if v_user.id is null then
    select * into v_user
    from public.bot_users
    where telegram_user_id=v_user_id;

    if found then
      if v_user.chat_id is distinct from v_chat_id
         or v_user.username is distinct from v_username
         or v_user.first_name is distinct from v_first_name
         or v_user.last_name is distinct from v_last_name
         or v_user.language_code is distinct from v_language_code
      then
        update public.bot_users
        set chat_id=v_chat_id,
            username=v_username,
            first_name=v_first_name,
            last_name=v_last_name,
            language_code=v_language_code,
            updated_at=now()
        where id=v_user.id
        returning * into v_user;
      end if;
    else
      insert into public.bot_users(
        telegram_user_id,chat_id,username,first_name,last_name,
        language_code,last_start_at,origin
      )
      values(
        v_user_id,v_chat_id,v_username,v_first_name,v_last_name,
        v_language_code,now(),'telegram'
      )
      returning * into v_user;
      v_is_new:=true;
    end if;
  end if;

  select * into v_subscription
  from public.user_subscriptions
  where user_id=v_user.id;

  return jsonb_build_object(
    'claim',v_claim,
    'is_new_user',v_is_new,
    'user',to_jsonb(v_user),
    'subscription',case when v_subscription.id is null then null else to_jsonb(v_subscription) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.preserve_verified_portal_warm_rent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.source_id in (1, 3)
     and new.warm_rent is null
     and old.warm_rent is not null
     and old.warm_rent_is_calculated is false then
    new.warm_rent := old.warm_rent;
    new.warm_rent_is_calculated := false;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_saga_recovery(p_listing_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  l public.listings%rowtype;
  v_ref text;
  v_status text;
  v_checked timestamptz;
  v_count integer:=0;
begin
  select * into l from public.listings where id=p_listing_id;
  if not found then return 0; end if;

  v_ref:=app_private.saga_object_ref(l.raw,l.enrichment_evidence);
  v_status:=l.enrichment_evidence#>>'{saga_probe,immomio_status}';
  begin
    v_checked:=(l.enrichment_evidence#>>'{saga_probe,checked_at}')::timestamptz;
  exception when others then
    v_checked:=null;
  end;

  if l.source_id not in (1,3)
     or not l.is_active
     or not coalesce(l.is_primary_listing,false)
     or coalesce(l.quality_status,'unchecked')='rejected'
     or l.first_seen_at >= statement_timestamp()-interval '24 hours'
     or v_ref is null
     or v_status<>'online'
     or v_checked is null
     or v_checked < statement_timestamp()-interval '10 minutes'
  then
    return 0;
  end if;

  insert into public.delivery_events(
    profile_id,listing_id,dedupe_key,status,delivery_format,
    recipient_user_id,event_type,next_retry_at,channel
  )
  select
    p.id,
    l.id,
    'saga:'||v_ref,
    case when u.telegram_user_id is not null and u.chat_id is not null then 'pending' else 'available' end,
    case when u.telegram_user_id is not null and u.chat_id is not null then 'photo_card' else 'web_match' end,
    p.user_id,
    'still_active',
    null,
    case when u.telegram_user_id is not null and u.chat_id is not null then 'telegram' else 'web' end
  from public.search_profiles p
  join public.bot_users u on u.id=p.user_id and u.is_active=true
  where p.is_active=true
    and (p.profile_slot=1 or app_private.user_is_premium(p.user_id))
    and app_private.matches_property_filters(p,l)
    and not exists (
      select 1
      from public.delivery_events de
      join public.listings oldl on oldl.id=de.listing_id
      where de.recipient_user_id=p.user_id
        and de.status='sent'
        and (
          app_private.saga_object_ref(oldl.raw,oldl.enrichment_evidence)=v_ref
          or oldl.dedupe_group_id=l.dedupe_group_id
        )
    )
  on conflict do nothing;

  get diagnostics v_count=row_count;
  return v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.reconcile_source_category(p_source_id smallint, p_category text, p_token uuid, p_keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;begin
 if p_keys is null or cardinality(p_keys)>10000 or not exists(select 1 from app_private.source_category_streams where source_id=p_source_id and category=p_category and lease_token=p_token and lease_until>now() and enabled) then raise exception 'category_reconcile_not_authorized';end if;
 update public.listings set is_active=false where source_id=p_source_id and raw->>'category_stream'=p_category and is_active and not (source_listing_key=any(p_keys));
 get diagnostics n=row_count;return n;
end $function$

CREATE OR REPLACE FUNCTION public.record_saga_probe(p_listing_id uuid, p_is_saga boolean, p_saga_ref text, p_application_url text, p_immomio_status text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ref text;
  v_url text;
  v_probe jsonb;
  v_group uuid;
  v_primary boolean;
  v_next timestamptz;
  v_status text;
  v_error text;
  v_shared_from uuid;
  v_verified_source uuid;
  v_propagated integer:=0;
begin
  if not exists(select 1 from public.listings where id=p_listing_id) then
    raise exception 'listing_not_found';
  end if;

  v_ref:=upper(regexp_replace(regexp_replace(btrim(coalesce(p_saga_ref,'')),'[[:space:]]*/[[:space:]]*','/','g'),'[[:space:]]+',' ','g'));
  if v_ref !~ '^MO [0-9]{4}/[A-Z0-9.-]+/[A-Z0-9.-]+$' then v_ref:=null; end if;

  v_url:=nullif(btrim(coalesce(p_application_url,'')),'');
  if v_url is not null and v_url !~* '^https://tenant[.]immomio[.]com/(de/)?apply/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/?$' then
    v_url:=null;
  end if;

  v_status:=nullif(btrim(coalesce(p_immomio_status,'')),'');
  v_error:=nullif(left(coalesce(p_error,''),500),'');

  if coalesce(p_is_saga,false) and v_ref is not null and v_url is null then
    select l.id,
           coalesce(
             nullif(l.raw->>'applicationLink',''),
             nullif(l.enrichment_evidence#>>'{saga_probe,application_url}',''),
             nullif(l.enrichment_evidence#>>'{saga_shared,application_url}','')
           )
      into v_shared_from,v_url
    from public.listings l
    where l.id<>p_listing_id
      and app_private.saga_object_ref(l.raw,l.enrichment_evidence)=v_ref
      and (
        l.enrichment_evidence#>>'{saga_probe,immomio_status}'='online'
        or l.enrichment_evidence#>>'{saga_shared,verified}'='true'
      )
      and coalesce(
        nullif(l.raw->>'applicationLink',''),
        nullif(l.enrichment_evidence#>>'{saga_probe,application_url}',''),
        nullif(l.enrichment_evidence#>>'{saga_shared,application_url}','')
      ) ~* '^https://tenant[.]immomio[.]com/(de/)?apply/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/?$'
    order by greatest(
      coalesce((l.enrichment_evidence#>>'{saga_probe,checked_at}')::timestamptz,'-infinity'::timestamptz),
      coalesce((l.enrichment_evidence#>>'{saga_shared,verified_at}')::timestamptz,'-infinity'::timestamptz)
    ) desc
    limit 1;

    if v_url is not null then
      v_status:='online';
      v_error:=null;
    end if;
  end if;

  if v_error is not null then
    v_next:=statement_timestamp()+interval '1 hour';
  end if;

  v_probe:=jsonb_strip_nulls(jsonb_build_object(
    'checked_at',statement_timestamp(),
    'status',case
      when v_error is not null then 'error'
      when coalesce(p_is_saga,false) then 'identified'
      else 'not_saga'
    end,
    'next_check_at',v_next,
    'is_saga',coalesce(p_is_saga,false),
    'saga_object_ref',v_ref,
    'application_url',v_url,
    'immomio_status',v_status,
    'verification_source',case when v_shared_from is not null then 'shared_mo_ref' else 'direct' end,
    'error',v_error
  ));

  update public.listings
  set enrichment_evidence=jsonb_set(coalesce(enrichment_evidence,'{}'::jsonb),'{saga_probe}',v_probe,true),
      raw=case when coalesce(p_is_saga,false) then
        coalesce(raw,'{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'provider_entity','SAGA',
          'saga_object_ref',v_ref,
          'applicationLink',v_url
        ))
      else raw end
  where id=p_listing_id;

  if coalesce(p_is_saga,false) and v_ref is not null then
    v_group:=app_private.assign_listing_dedupe(p_listing_id);
  end if;

  if coalesce(p_is_saga,false)
     and v_ref is not null
     and v_url is not null
     and v_status='online'
  then
    v_verified_source:=coalesce(v_shared_from,p_listing_id);

    update public.listings l
    set raw=(
          coalesce(l.raw,'{}'::jsonb)
          || jsonb_build_object('provider_entity','SAGA','saga_object_ref',v_ref)
          || case
               when coalesce(l.raw->>'applicationLink','') ~* '^https://tenant[.]immomio[.]com/(de/)?apply/[0-9a-f-]{36}/?$'
                 then '{}'::jsonb
               else jsonb_build_object('applicationLink',v_url)
             end
        ),
        enrichment_evidence=jsonb_set(
          coalesce(l.enrichment_evidence,'{}'::jsonb),
          '{saga_shared}',
          jsonb_build_object(
            'verified',true,
            'application_url',v_url,
            'verified_at',statement_timestamp(),
            'verified_source_listing_id',v_verified_source
          ),
          true
        )
    where app_private.saga_object_ref(l.raw,l.enrichment_evidence)=v_ref
      and (
        coalesce(l.raw->>'applicationLink','') !~* '^https://tenant[.]immomio[.]com/(de/)?apply/[0-9a-f-]{36}/?$'
        or l.enrichment_evidence#>>'{saga_shared,verified}' is distinct from 'true'
        or l.enrichment_evidence#>>'{saga_shared,application_url}' is distinct from v_url
      );

    get diagnostics v_propagated=row_count;
  end if;

  select is_primary_listing,dedupe_group_id
    into v_primary,v_group
  from public.listings where id=p_listing_id;

  return jsonb_build_object(
    'ok',true,
    'is_saga',coalesce(p_is_saga,false),
    'saga_object_ref',v_ref,
    'application_url',v_url,
    'immomio_status',v_status,
    'inherited_from_listing_id',v_shared_from,
    'propagated_count',v_propagated,
    'dedupe_group_id',v_group,
    'is_primary_listing',coalesce(v_primary,false)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.record_telegram_fast_metric(p_update_id bigint, p_metrics jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare safe jsonb; region text;
begin
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into safe
 from jsonb_each(coalesce(p_metrics,'{}'::jsonb))
 where key in('db_ms','render_ms','ack_ms','response_ms','telegram_ms','total_ms','rpc_count','telegram_count','busy_count','fast_path')
   and jsonb_typeof(value)='number' and value::numeric between 0 and 600000;
 region:=left(coalesce(p_metrics->>'edge_region',''),32);
 if region~'^[a-z0-9-]{2,32}$' then safe:=safe||jsonb_build_object('edge_region',region); end if;
 update public.bot_events set ui_timings=coalesce(ui_timings,'{}'::jsonb)||safe
 where telegram_update_id=p_update_id and processing_status='done';
 return found;
end $function$

