CREATE OR REPLACE FUNCTION public.redeem_referral_code(p_referred_user_id uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_referrer_user_id uuid;
  v_existing public.referrals%rowtype;
begin
  if p_referred_user_id is null or nullif(trim(p_code), '') is null then
    return jsonb_build_object('status', 'invalid_code');
  end if;

  select rc.user_id into v_referrer_user_id
  from public.referral_codes rc
  where lower(rc.code) = lower(trim(p_code))
    and rc.active = true
  limit 1;

  if v_referrer_user_id is null then
    return jsonb_build_object('status', 'invalid_code');
  end if;
  if v_referrer_user_id = p_referred_user_id then
    return jsonb_build_object('status', 'self_referral');
  end if;

  select * into v_existing
  from public.referrals r
  where r.referred_user_id = p_referred_user_id
  limit 1;

  if v_existing.id is not null then
    return jsonb_build_object('status', 'already_registered');
  end if;

  if exists (
    select 1
    from public.search_profiles sp
    where sp.user_id = p_referred_user_id
  ) then
    return jsonb_build_object('status', 'not_new_user');
  end if;

  insert into public.referrals(
    referrer_user_id,
    referred_user_id,
    status
  ) values (
    v_referrer_user_id,
    p_referred_user_id,
    'registered'
  );

  return jsonb_build_object(
    'status', 'registered',
    'referrer_user_id', v_referrer_user_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_search_profile_ui(p_user uuid, p_update_id bigint, p_attempt integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  u public.bot_users%rowtype;
  reward jsonb;
begin
  select * into u from public.bot_users where id=p_user for update;
  if not found
     or not u.is_active
     or not exists(
       select 1 from public.bot_events
       where telegram_update_id=p_update_id
         and telegram_user_id=u.telegram_user_id
         and processing_status='processing'
         and processing_attempt=p_attempt
     ) then
    raise exception 'ui_lease_lost';
  end if;

  if coalesce(p_values->>'_flow','')!~'^[a-f0-9]{12}$' then
    raise exception 'ui_state_changed';
  end if;
  if coalesce(u.onboarding_state->>'_flow','')<>coalesce(p_values->>'_flow','')
     or coalesce(u.onboarding_state->>'_revision','0')<>coalesce(p_values->>'_revision','0') then
    raise exception 'ui_state_changed';
  end if;

  perform app_private.save_search_profile_values(p_user,p_values);

  update public.bot_users
  set onboarding_step=null,onboarding_state='{}',updated_at=now()
  where id=p_user;

  reward:=public.complete_referral_reward(p_user);
  return coalesce(reward,'{}'::jsonb);
end
$function$

CREATE OR REPLACE FUNCTION public.save_ui_state(p_user uuid, p_update_id bigint, p_attempt integer, p_step text, p_state jsonb, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare u public.bot_users%rowtype;current_revision integer;result jsonb;
begin
 select * into u from public.bot_users where id=p_user for update;
 if not found or not u.is_active or not exists(select 1 from public.bot_events where telegram_update_id=p_update_id and telegram_user_id=u.telegram_user_id and processing_status='processing' and processing_attempt=p_attempt) then raise exception 'ui_lease_lost';end if;
 if p_state is null or jsonb_typeof(p_state)<>'object' or octet_length(p_state::text)>24000 or p_step not in ('types','location','boroughs','neighborhoods','rent','rent_custom','rooms','area','roomarea','options','review','applicant_setup') then
  if p_step is not null then raise exception 'invalid_ui_state';end if;
 end if;
 current_revision:=coalesce((u.onboarding_state->>'_revision')::integer,0);
 if current_revision<>p_revision then raise exception 'ui_state_changed';end if;
 if u.onboarding_step is not distinct from p_step and (coalesce(u.onboarding_state,'{}')-'_revision')=(coalesce(p_state,'{}')-'_revision') then return coalesce(u.onboarding_state,'{}');end if;
 result:=case when p_step is null then '{}'::jsonb else jsonb_set(p_state,'{_revision}',to_jsonb(current_revision+1),true) end;
 update public.bot_users set onboarding_step=p_step,onboarding_state=result,updated_at=now() where id=p_user;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.set_application_enabled_shared(p_user uuid, p_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists(select 1 from public.bot_users where id=p_user and is_active) then
    raise exception 'participant_unavailable';
  end if;
  if p_enabled and not app_private.user_is_premium(p_user) then
    raise exception 'premium_required';
  end if;
  if p_enabled and not app_private.applicant_profile_identity_ready(p_user) then
    raise exception 'profile_incomplete';
  end if;
  if p_enabled and not app_private.user_has_application_provider(p_user) then
    raise exception 'provider_required';
  end if;

  insert into public.application_preferences(
    user_id,enabled,immoscout_enabled,kleinanzeigen_enabled,immomio_enabled,immowelt_enabled
  )
  values(p_user,p_enabled,p_enabled,p_enabled,p_enabled,p_enabled)
  on conflict(user_id) do update
  set enabled=excluded.enabled,
      updated_at=now();

  update public.bot_users
  set auto_apply_enabled=p_enabled,updated_at=now()
  where id=p_user;

  if not p_enabled then
    update public.applications
    set status='failed',
        last_error='auto_apply_disabled',
        wait_reason=null,
        lease_until=null,
        next_attempt_at=null
    where user_id=p_user
      and status='pending'
      and submission_started_at is null;
  end if;

  return true;
end
$function$

